from typing import Dict, Any, List, Literal
from datetime import datetime, timezone

class LogEvent:
    def __init__(self, message: str, severity: str, timestamp_ms: int, properties: Dict[str, Any]):
        self.message = message
        self.severity = severity
        self.timestamp_ms = timestamp_ms
        self.properties = properties

    def to_azure_monitor_log(self) -> Dict[str, Any]:
        event = {
            "Message": self.message,
            "Severity": self.severity,
            "TimeGenerated": datetime.fromtimestamp(self.timestamp_ms / 1000, tz=timezone.utc).isoformat(),
        }
        event.update(self.properties)
        return event

class LogQueryRequest:
    def __init__(self, workspace_id: str, query: str, timespan: str = "PT1H"):
        self.workspace_id = workspace_id
        self.query = query
        self.timespan = timespan

class LogQueryResponse:
    def __init__(self, tables: List[Dict[str, Any]]):
        self.tables = tables

    def to_dict(self) -> Dict[str, Any]:
        return {"tables": self.tables}

class SummarizationRequest:
    def __init__(self, log_entries: List[str]):
        self.log_entries = log_entries

class SafetyCheckRequest:
    def __init__(self, text: str):
        self.text = text

class TranslationRequest:
    def __init__(self, text: str, target_language: str):
        self.text = text
        self.target_language = target_language

class EmbeddingRequest:
    def __init__(self, text: str):
        self.text = text

import time
import uuid
from observability_client import get_ingestion_client
from observability_models import LogEvent

def write_correlated_logs(messages: list[str], correlation_id: str | None = None, severity: str = "Informational"):
    if correlation_id is None:
        correlation_id = str(uuid.uuid4())

    client, rule_id, stream_name = get_ingestion_client()

    logs_to_upload = []
    for message in messages:
        event_payload = {
            "Message": message,
            "CorrelationId": correlation_id,
        }
        log_event = LogEvent(
            message=message,
            severity=severity,
            timestamp_ms=int(time.time() * 1000),
            properties=event_payload
        )
        logs_to_upload.append(log_event.to_azure_monitor_log())

    client.upload(rule_id=rule_id, stream_name=stream_name, logs=logs_to_upload)
    return {"submitted": True, "correlation_id": correlation_id}
